package com.pixilife.android;
import android.Manifest;import android.app.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.location.*;import android.os.*;import android.widget.*;import java.io.*;import java.net.*;import org.json.*;
public class WeatherActivity extends Activity {
 private TextView out;@Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(30,30,30,30);r.setBackgroundColor(Color.rgb(7,11,17));out=new TextView(this);out.setTextColor(Color.WHITE);out.setTextSize(18);r.addView(out);Button x=new Button(this);x.setText("Actualizar clima real");x.setOnClickListener(v->load());r.addView(x);setContentView(r);load();}
 private void load(){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){out.setText("Falta permiso de ubicación.");return;}LocationManager m=getSystemService(LocationManager.class);Location best=null;for(String p:m.getProviders(true)){try{Location l=m.getLastKnownLocation(p);if(l!=null&&(best==null||l.getTime()>best.getTime()))best=l;}catch(Exception ignored){}}if(best==null){out.setText("Esperando una ubicación real…");return;}double lat=best.getLatitude(),lon=best.getLongitude();out.setText("Consultando Open-Meteo…");new Thread(()->{try{URL u=new URL("https://api.open-meteo.com/v1/forecast?latitude="+lat+"&longitude="+lon+"&current=temperature_2m,apparent_temperature,relative_humidity_2m,precipitation,wind_speed_10m&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=auto");BufferedReader br=new BufferedReader(new InputStreamReader(u.openStream()));StringBuilder s=new StringBuilder();String q;while((q=br.readLine())!=null)s.append(q);JSONObject j=new JSONObject(s.toString()),c=j.getJSONObject("current"),d=j.getJSONObject("daily");String a="Ahora: "+c.optDouble("temperature_2m")+" °C\nSensación: "+c.optDouble("apparent_temperature")+" °C\nHumedad: "+c.optInt("relative_humidity_2m")+" %\nViento: "+c.optDouble("wind_speed_10m")+" km/h\nMáxima: "+d.getJSONArray("temperature_2m_max").optDouble(0)+" °C\nMínima: "+d.getJSONArray("temperature_2m_min").optDouble(0)+" °C\nProbabilidad de lluvia: "+d.getJSONArray("precipitation_probability_max").optInt(0)+" %";runOnUiThread(()->out.setText(a));}catch(Exception e){runOnUiThread(()->out.setText("No se pudo obtener clima real: "+e.getMessage()));}}).start();}
}
